 await page2.locator("#btnRoster").click();
 const importBlob=async(obj)=>{const chooser=page2.waitForEvent("filechooser");await page2.locator("#actImport").click();await (await chooser).setFiles({name:"audit.json",mimeType:"application/json",buffer:Buffer.from(JSON.stringify(obj),"utf8")});await page2.waitForTimeout(80)};
 await importBlob(backup);
 const roundtrip=await page2.evaluate(()=>({count:getRoster().length,roster:getRoster().map(x=>x.name),copies:getRoster().map(x=>JSON.parse(localStorage.getItem(SK.char(x.id))))}));
 observations.push({flow:"roster-backup-roundtrip",count:roundtrip.count,sourceCount:backup.chars.length,subName:roundtrip.copies[0]?.subName,languageChoices:roundtrip.copies[0]?.languageChoices});
 assert.equal(roundtrip.count,backup.chars.length);
