 await importBlob(incomplete);
 const malformed=await page2.evaluate(()=>({rows:getRoster().length,broken:getRoster().find(x=>x.id==="broken-but-accepted")||null,raw:localStorage.getItem(SK.char("broken-but-accepted"))}));
 observations.push({flow:"malformed-backup-import",accepted:!!malformed.broken,rawStored:!!malformed.raw,entry:malformed.broken});
 if(malformed.broken)findings.push({id:"INVALID-ROSTER-ENTRY",severity:"medium",description:"Bulk backup accepts incomplete native Save and creates unusable phantom roster entry",entry:malformed.broken});
