 if(afterTruncated!==roundtrip.count)findings.push({id:"BACKUP-COUNT-MISMATCH",severity:"high",description:"Truncated declared backup changed character roster"});
 const bareMalformed={v:10,ruleset:"2024",id:"bad-native-single",base:{},cls:null,level:99,meta:{name:"錯誤單角存檔"}};
 await importBlob(bareMalformed);
 const badNative=await page2.evaluate(()=>({rows:getRoster().length,entry:getRoster().find(x=>x.name==="錯誤單角存檔")||null}));
 observations.push({flow:"invalid-single-save",...badNative});
 if(badNative.entry)findings.push({id:"INVALID-NATIVE-SINGLE",severity:"high",description:"Malformed native single-save bypasses validation and enters roster",entry:badNative.entry});
 const future=JSON.parse(JSON.stringify(backup.chars[0]));future.id="future-schema-original";future.meta.name="未來版本稽核";future.v=99;future.futureOnlyMarker="keep-exactly";
 await importBlob(future);
 const futureImport=await page2.evaluate(()=>({roster:getRoster().filter(x=>x.name==="未來版本稽核"),saved:[...Array.from({length:localStorage.length},(_,i)=>localStorage.key(i)).filter(k=>k?.startsWith("dnd5r:char:"))].map(k=>JSON.parse(localStorage.getItem(k))).filter(c=>c.meta?.name==="未來版本稽核").map(c=>({v:c.v,marker:c.futureOnlyMarker??null}))}));
 observations.push({flow:"future-version-single-import",...futureImport});
 if(futureImport.roster.length)findings.push({id:"FUTURE-VERSION-DOWNGRADE",severity:"critical",description:"Newer-schema Save is accepted and rewritten with older SAVE_VERSION, dropping unknown data",saved:futureImport.saved});
 await importBlob({type:"dnd5r-roster",v:99,count:1,chars:[future]});
 const futureBackup=await page2.evaluate(()=>({saved:JSON.parse(localStorage.getItem(SK.char("future-schema-original"))||"null"),loadDisabled:document.querySelector('#rosterList [data-load="future-schema-original"]')?.disabled,dupDisabled:document.querySelector('#rosterList [data-dup="future-schema-original"]')?.disabled}));
 observations.push({flow:"future-version-backup-preservation",version:futureBackup.saved?.v,marker:futureBackup.saved?.futureOnlyMarker,loadDisabled:futureBackup.loadDisabled,dupDisabled:futureBackup.dupDisabled});
 const historical=JSON.parse(JSON.stringify(backup.chars[0]));historical.id="old-numeric-string";historical.v=8;historical.level="3";historical.base.str="12";historical.meta.name="舊數字字串存檔";
 await importBlob({type:"dnd5r-roster",v:8,count:1,chars:[historical]});
