 if(futureBackup.saved?.futureOnlyMarker!=="keep-exactly"||futureBackup.loadDisabled!==true)findings.push({id:"FUTURE-BACKUP-PRESERVATION",severity:"critical",description:"Newer version backup lost original marker or remained editable"});
 const futureDl=page2.waitForEvent("download");await page2.locator('#rosterList [data-exp="future-schema-original"]').click();const futureOut=JSON.parse(fs.readFileSync(await (await futureDl).path(),"utf8"));
 assert.equal(futureOut.futureOnlyMarker,"keep-exactly","future backup must remain exportable exactly");
 if(!await page2.locator("#rosterModal.open").count())await page2.locator("#btnRoster").click();
